package com.edgecloud.device.controller;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;import static org.mockito.Mockito.*;import com.edgecloud.device.security.*;import com.edgecloud.device.service.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.web.servlet.MockMvc;
@WebMvcTest(DeviceHeartbeatController.class) @Import({DeviceSecurityConfig.class,EdgeCloudJwtAuthenticationFilter.class,JwtService.class}) class DeviceHeartbeatControllerTest {@Autowired MockMvc mvc;@MockBean DeviceHeartbeatService service;@MockBean ProjectScopeClient projects;String id="11111111-1111-1111-1111-111111111111",project="22222222-2222-2222-2222-222222222222";
 @Test void rejectsUnauthenticatedAndViewer()throws Exception{mvc.perform(get("/management/"+id+"/heartbeat")).andExpect(status().isUnauthorized());mvc.perform(get("/management/"+id+"/heartbeat").header("Authorization",bearer("VIEWER"))).andExpect(status().isForbidden());}
 @Test void permitsAdminAndOperatorDetailsHistoryStatistics()throws Exception{for(String role:new String[]{"ADMIN","OPERATOR"}){String token=bearer(role);mvc.perform(get("/management/"+id+"/heartbeat").header("Authorization",token)).andExpect(status().isOk());mvc.perform(get("/management/"+id+"/heartbeat/history").header("Authorization",token)).andExpect(status().isOk());mvc.perform(get("/management/"+id+"/heartbeat/statistics").header("Authorization",token)).andExpect(status().isOk());}}
 @Test void projectAdminUsesProjectScopedAccess()throws Exception{String token=bearer("PROJECT_ADMIN");mvc.perform(get("/management/"+id+"/heartbeat").header("Authorization",token)).andExpect(status().isForbidden());mvc.perform(get("/management/projects/"+project+"/devices/"+id+"/heartbeat").header("Authorization",token)).andExpect(status().isOk());verify(projects).requireDeviceAssociation(eq(java.util.UUID.fromString(project)),eq(java.util.UUID.fromString(id)),anyString());}
 private String bearer(String role){return "Bearer "+TestJwtHelper.jwt(role);}
}
